package main

import (
	"fmt"
	"strings"
)

func splitSegments(p string) (segs []string, absolute bool) {
	p = strings.TrimSpace(p)
	if p == "" {
		return nil, false
	}
	p = strings.ReplaceAll(p, `\`, "/")
	p = strings.TrimRight(p, "/")
	if p == "" {
		return nil, false
	}
	raw := strings.Split(p, "/")
	absolute = raw[0] == ""
	out := raw[:0]
	for _, s := range raw {
		if s == "" || s == "." {
			continue
		}
		out = append(out, s)
	}
	if len(out) == 0 {
		return nil, absolute
	}
	return out, absolute
}

func canon(p string) string {
	segs, absolute := splitSegments(p)
	if len(segs) == 0 {
		return "<empty>"
	}
	joined := strings.Join(segs, "/")
	if absolute {
		return "/" + joined
	}
	return joined
}

func main() {
	cases := []string{"/", "//", "//docs/x.md", `\docs\x.md`, `docs\x.md`, "//docs//x.md", "/./docs/x.md"}
	for _, c := range cases {
		segs, abs := splitSegments(c)
		fmt.Printf("%-20q segs=%v absolute=%v canon=%q\n", c, segs, abs, canon(c))
	}
}
EOF
go run /tmp/absotest.go

